-- 0128: the 13 built-in industry templates become database rows (#2633).
--
-- Two template systems exist today and only one is wired: the hardcoded map
-- (lib/modules/industry-templates.ts) drives every tenant-side apply, while
-- product_templates/tenant_templates back the superadmin UI — whose assign
-- path records an assignment and materializes NOTHING (no pipelines, fields
-- or automations ever insert). A template created in the admin UI therefore
-- changes nothing — the split-brain class #2597 was. This migration makes
-- product_templates the single source of truth that lib/templates/apply-template.ts
-- and lib/templates/resolve.ts read; the hardcoded map survives only as the
-- seed source for the INSERTs below.
--
-- The writes run behind set_config('app.is_super_admin','true',true) because
-- product_templates' only write policy is product_templates_super_admin_write
-- (ALL, gated on that GUC): without the SET, this migration seeds ZERO rows
-- silently on any host whose migrate role is not a superuser — the exact
-- PP-058/0125 class guard:migration-rls screens for. The superadmin-only
-- table is precisely the one place an unblinded seed cannot leak tenant data.
--
-- slug keeps the current hardcoded id (legal, saas, ...) so every existing
-- caller (onboarding templateId, installTemplateModules lookups, tests) keeps
-- resolving unchanged. created_by stays NULL: no FK-resolvable platform user
-- is guaranteed on a fresh database. is_builtin rows are protected from
-- content edits in the superadmin PATCH route, not here.

ALTER TABLE "product_templates" ADD COLUMN IF NOT EXISTS "default_dashboard_layout" jsonb;

DO $$
BEGIN
  PERFORM set_config('app.is_super_admin', 'true', true);

  INSERT INTO "product_templates"
    ("slug", "name", "description", "icon", "modules", "custom_fields", "pipelines", "automations", "default_dashboard_layout", "is_builtin", "status")
    VALUES
